<script setup lang="ts">
import {ref,onMounted,watch,computed} from 'vue'
import {api,post,type Inbox,type Notice} from '../api'
const emit=defineEmits<{navigate:[page:string,id?:string];changed:[]}>()
const result=ref<Inbox>({items:[],total:0,unread:0,page:1,size:20}),page=ref(1),unread=ref(false),loading=ref(false),working=ref(false),error=ref('')
const busy=computed(()=>loading.value||working.value)
let sequence=0
async function load(){const current=++sequence;loading.value=true;error.value='';try{const latest=await api<Inbox>(`/notifications?page=${page.value}&size=20&unread=${unread.value}`);if(current===sequence){result.value=latest;if(page.value!==latest.page)page.value=latest.page}}catch(e){if(current===sequence)error.value=(e as Error).message}finally{if(current===sequence)loading.value=false}}
async function open(n:Notice){if(busy.value)return;working.value=true;error.value='';try{await post(`/notifications/${n.id}/read`);emit('changed');emit('navigate',n.target_type||n.path,n.target_id||undefined);await load()}catch(e){error.value=(e as Error).message}finally{working.value=false}}
async function readAll(){if(busy.value)return;working.value=true;error.value='';try{await post('/notifications/read-all');emit('changed');await load()}catch(e){error.value=(e as Error).message}finally{working.value=false}}
watch([page,unread],([p,u],[,previous])=>{if(u!==previous&&p!==1){page.value=1;return}void load()});onMounted(load)
</script>
<template><section class="panel"><div class="table-toolbar"><div class="toolbar-filters"><strong>未读 {{result.unread}} 条</strong><label class="checkbox-label"><input v-model="unread" type="checkbox"/>只看未读</label></div><button class="btn" :disabled="busy" @click="load">刷新通知</button><button class="btn" :disabled="busy||!result.unread" @click="readAll">全部标为已读</button></div><p v-if="error" class="form-error" role="alert">{{error}} <button class="btn" :disabled="busy" @click="load">重新加载</button></p><p v-if="loading" class="form-hint" role="status">正在读取通知…</p><button v-for="n in result.items" :key="n.id" class="notification-row" :class="{unread:!n.read_at}" :disabled="busy" @click="open(n)"><span class="notice-marker"></span><div><strong>{{n.title}}</strong><p>{{n.body}}</p><small>{{n.created_at.replace('T',' ').slice(0,16)}} · {{n.read_at?'已读':'未读'}}</small></div><span class="muted">查看 →</span></button><div v-if="!result.items.length&&!busy&&!error" class="empty">{{unread?'没有未读通知。':'暂时没有通知，业务进展会在这里提醒你。'}}</div><div class="table-footer"><span>共 {{result.total}} 条通知</span><div><button class="btn compact" :disabled="page===1||busy" @click="page--">上一页</button><span>{{page}} / {{Math.max(1,Math.ceil(result.total/20))}}</span><button class="btn compact" :disabled="page*20>=result.total||busy" @click="page++">下一页</button></div></div></section></template>
